mapper.select:
SELECT wq.id, wq.user_id, wq.question_id, wq.attempt_id, wq.status, wq.wrong_count, wq.last_wrong_time, wq.next_review_time, wq.created_time, q.title AS question_title, q.difficulty AS question_difficulty, q.tags AS question_tags, q.category_id AS question_category_id FROM portal_wrong_question wq LEFT JOIN portal_interview_question q ON q.id = wq.question_id
AND wq.user_id = #{userId}
AND wq.status = #{query.status}
AND q.tags LIKE CONCAT('%', #{query.tag}, '%')
AND q.title LIKE CONCAT('%', #{query.keyword}, '%')
ORDER BY wq.last_wrong_time DESC
